import {canonicalImportedTransformTracks} from './sequence-indexed-transforms.js';
import {AnimationClip,LoopOnce} from 'three';
import {validAsset} from './asset-documents.js';
import {sampleTimeline,timelineLength} from './blueprint-model.js';
import {ImportedSequenceTransformProgram} from './sequence-imported-transforms.js';
import {ImportedSequencePoseProgram} from './sequence-imported-pose.js';
import {blendSequenceEntries} from './sequence-blending.js';

// Layer keys are playback-owner identities, not clip names: the same clip can
// be evaluated at two different section clocks without duplicating its tracks.
export function mixSequenceAnimationEntries(entries){return {...entries[0].value,layers:entries.map(e=>({owner:e.owner,sample:e.value,weight:e.owner.weight??1}))};}
const source=layer=>layer.sample.clip.clip;
const clock=(layer,length)=>Math.max(0,Math.min(length,layer.sample.time));
const trs=new Set(['position','rotation','scale']);
export class SequenceAnimationMixing{
 constructor({asset,readAsset,update,reconcileTRS}){Object.assign(this,{asset,readAsset,update,reconcileTRS});this.storedClips=new WeakMap();this.posePrograms=new WeakMap();this.transformPrograms=new WeakMap();}
 transforms(group,clip){let groups=this.transformPrograms.get(clip);if(!groups){groups=new WeakMap();this.transformPrograms.set(clip,groups);}let program=groups.get(group);if(!program){program=new ImportedSequenceTransformProgram(group,clip);groups.set(group,program);}return program;}
 async storedClip(name){const path=await this.asset(name,'skeletalclip');if(!path?.endsWith('.hbskeletalclip.json'))return null;const data=await this.readAsset(path);if(!validAsset('skeletalclip',data)||!data.tracks.length)throw Error('골격 클립 검증 실패');let clip=this.storedClips.get(data);if(!clip){clip=AnimationClip.parse(data);this.storedClips.set(data,clip);}return clip;}
 imported(group,clip){let groups=this.posePrograms.get(clip);if(!groups){groups=new WeakMap();this.posePrograms.set(clip,groups);}let pose=groups.get(group);if(!pose){pose=new ImportedSequencePoseProgram(group,clip);groups.set(group,pose);}const binding=pose.binding(group);return {kind:'mixer',clip,pose:binding.signature.names.length?pose:undefined,transforms:this.transforms(group,clip)};}
 async program(player,name,group){
  const clip=group?.userData.animations?.find(c=>c.name===name);if(clip)return this.imported(group,clip);
  player.sequencePrograms??=new Map();let pending=player.sequencePrograms.get(name);if(!pending){pending=(async()=>{const stored=await this.storedClip(name);if(stored)return this.imported(group,stored);const path=await this.asset(name,'animation')||await this.asset(name,'spriteanimation');if(!path)throw Error('애니메이션 클립이나 에셋이 없어요: '+name);if(path.endsWith('.hbspriteanimation.json'))return {kind:'sprite'};const data=await this.readAsset(path);if(!validAsset('animation',data))throw Error('애니메이션 에셋 검증 실패');const timeline=data.timeline,tracks=timeline.tracks.filter(t=>trs.has(t.id));if(!tracks.length||tracks.some(t=>t.type!=='vec3'||!t.keys.length))throw Error('애니메이션의 position/rotation/scale 트랙은 키가 있는 Vector여야 해요.');return {kind:'timeline',timeline,tracks,length:timelineLength(timeline)};})();player.sequencePrograms.set(name,pending);pending.catch(()=>{if(player.sequencePrograms?.get(name)===pending)player.sequencePrograms.delete(name);});}return pending;
 }
 async sample(object,group,player,layers,current){
  const kind=player.mixer?'mixer':player.type==='sprite'?'sprite':'timeline',prepared=[];for(const layer of layers){const program=layer.sample.program??(kind!=='mixer'&&source(layer)===player.source?(kind==='timeline'?{kind,timeline:player.timeline,tracks:player.tracks,length:player.length}:{kind}):await this.program(player,source(layer),group));if(!current())return true;prepared.push({...layer,program});}
  const compatible=prepared.filter(p=>p.program.kind===kind),excluded=prepared.filter(p=>p.program.kind!==kind).map(p=>({source:source(p),kind:p.program.kind}));
  if(kind==='sprite'){player.sequenceBlend={kind:'discrete',layers:[{source:player.source,time:clock(prepared[0],player.length),weight:1}],excluded:prepared.slice(1).map(p=>({source:source(p),kind:p.program.kind}))};return false;}
  if(kind==='mixer')this.mixer(group,player,compatible);else this.timeline(object,player,compatible);
  const total=compatible.reduce((n,p)=>n+p.weight,0);player.sequenceBlend={kind,layers:compatible.map(p=>({source:source(p),time:clock(p,p.program.kind==='mixer'?p.program.clip.duration:p.program.length),weight:p.weight/total})),excluded};return true;
 }
 mixer(group,player,layers){
  const mixer=player.mixer;let actions=player.sequenceLayerActions;if(!actions){player.action.stop();mixer.uncacheAction(player.action.getClip(),group);player.sequenceLayerActions=actions=new Map();}
  const desired=new Map(layers.map(p=>[p.owner,p])),total=layers.reduce((n,p)=>n+p.weight,0);for(const [key,row]of actions)if(desired.get(key)?.program.clip!==row.original){row.action.stop();mixer.uncacheAction(row.clip,group);actions.delete(key);}
  for(const layer of layers){let row=actions.get(layer.owner);if(!row){const original=layer.program.clip,excluded=layer.sample.aliasPose||layer.sample.aliasTransforms?new Set([...(layer.program.pose?.binding(group).tracks||[]),...(layer.program.transforms?.binding(group).tracks||[])]):null,clip=new AnimationClip(original.name,original.duration,canonicalImportedTransformTracks(excluded?original.tracks.filter(track=>!excluded.has(track)):original.tracks),original.blendMode),action=mixer.clipAction(clip);row={original,clip,action};actions.set(layer.owner,row);action.setLoop(LoopOnce,1);action.clampWhenFinished=true;action.play();}const action=row.action;action.enabled=true;action.paused=true;action.time=clock(layer,row.clip.duration);action.setEffectiveWeight(layer.weight/total);}
  player.transformPrograms=layers.map(layer=>layer.program.transforms).filter(Boolean);player.aliasPoseTracks=layers.flatMap(layer=>[...(layer.sample.aliasPose?layer.program.pose?.binding(group).tracks||[]:[]),...(layer.sample.aliasTransforms?layer.program.transforms?.binding(group).tracks||[]:[])]);player.action=actions.get(layers[0].owner).action;player.length=layers[0].program.clip.duration;player.controlled=true;mixer.update(0);
 }
 timeline(object,player,layers){
  if(player.aliasTransforms){player.canonicalTransformFields=[...new Set(layers.flatMap(layer=>layer.program.tracks.map(track=>track.id)))];player.controlled=true;player.time=clock(layers[0],player.length);return;}
  const fields=new Map();for(const layer of layers)for(const track of layer.program.tracks){let rows=fields.get(track.id);if(!rows){rows=[];fields.set(track.id,rows);}const owner={blendMode:'normalized',priority:0,weight:layer.weight};rows.push({owner,mix:track.id==='rotation'?'rotation':'linear',value:sampleTimeline(track,clock(layer,layer.program.length))});}
  this.reconcileTRS(object,new Set(fields.keys()));for(const [field,rows]of fields)object[field]=blendSequenceEntries(rows[0],new Map(rows.map(row=>[row.owner,row]))).slice();player.controlled=true;player.time=clock(layers[0],player.length);this.update(object);
 }
}
export const sequenceAnimationMixingContract={owners:'Compatible animation clips at the winning priority normalize sequence weights. Existing override mode stays exclusive. Zero normalized animation weight yields while preserving the shared preanimated lease.',mixer:'One controlled THREE mixer per target, separate action per playback owner and independently clamped source clock; duplicate clip actions share the original keyframe tracks and typed buffers. Managed full/indexed bone TRS uses canonical recorded-pose leases and shared preanimated missing components; full/indexed actor-root/model-child TRS uses canonical field leases. Other bindings retain THREE normal-action behavior.',timeline:'Production HB animation position/rotation/scale tracks project into the same canonical field leases as direct and Transform component tracks; per-field priority, normalized vector/quaternion weights, completion and origin rules apply there. Legacy standalone callers keep local field mixing. Canonical restoration precedes old-evaluator presentation; held canonical poses restore captured actual values.',compatibility:'Canonical HB/imported actor TRS shares field arbitration across clip families; bone and model-child leases remain independent. Noncanonical imported properties and sprite selection use the winning compatible family, with excluded sources exposed in animationPlaybackState. Sprite frames are discrete; zero normalized weight still yields.',lifetime:'No ticking evaluator, new timer, worker or copied keyframe buffers. Action slots and prepared asset descriptors belong to the active controlled player and are retired on replacement/Stop. Async reads recheck playback ownership before writes.',remaining:['independent Euler-axis layer composition and renderer-parameter aliases','unmanaged external actions and arbitrary notify/async setter rollback']};
